"""Strict CSV parsing, formatting, JSON conversion, and command-line support."""

from __future__ import annotations

import csv
import io
import json
import sys
from collections.abc import Iterable, Mapping
from typing import Any


_HEADER = ["name", "note"]


def _parse_rows(text: str) -> list[list[str]]:
    """Parse CSV while enforcing quote placement more strictly than csv.reader."""
    if not isinstance(text, str):
        raise ValueError("CSV input must be a string")

    rows: list[list[str]] = []
    row: list[str] = []
    field: list[str] = []
    state = "start"  # start, unquoted, quoted, or after_quote
    ended_with_record_separator = False
    index = 0

    def finish_field() -> None:
        nonlocal field, state
        row.append("".join(field))
        field = []
        state = "start"

    def finish_row() -> None:
        nonlocal row
        finish_field()
        rows.append(row)
        row = []

    while index < len(text):
        char = text[index]

        if state == "quoted":
            if char == '"':
                if index + 1 < len(text) and text[index + 1] == '"':
                    field.append('"')
                    index += 2
                    continue
                state = "after_quote"
            else:
                field.append(char)
            ended_with_record_separator = False
            index += 1
            continue

        if state == "after_quote":
            if char == ",":
                finish_field()
                ended_with_record_separator = False
                index += 1
                continue
            if char == "\r" or char == "\n":
                finish_row()
                if char == "\r" and index + 1 < len(text) and text[index + 1] == "\n":
                    index += 1
                ended_with_record_separator = True
                index += 1
                continue
            raise ValueError(
                "malformed CSV: unexpected character after closing quote"
            )

        if char == ",":
            finish_field()
            ended_with_record_separator = False
        elif char == "\r" or char == "\n":
            finish_row()
            if char == "\r" and index + 1 < len(text) and text[index + 1] == "\n":
                index += 1
            ended_with_record_separator = True
        elif char == '"':
            if state != "start":
                raise ValueError("malformed CSV: quote in an unquoted field")
            state = "quoted"
            ended_with_record_separator = False
        else:
            field.append(char)
            state = "unquoted"
            ended_with_record_separator = False
        index += 1

    if state == "quoted":
        raise ValueError("malformed CSV: unterminated quoted field")

    if not ended_with_record_separator and (
        row or field or state != "start"
    ):
        finish_row()

    return rows


def parse_records(text: str) -> list[dict[str, str]]:
    """Parse CSV having exactly the header ``name,note``."""
    rows = _parse_rows(text)
    if not rows:
        raise ValueError("missing CSV header; expected name,note")
    if rows[0] != _HEADER:
        raise ValueError("invalid CSV header; expected name,note")

    records: list[dict[str, str]] = []
    for row_number, row in enumerate(rows[1:], start=2):
        if len(row) != 2:
            raise ValueError(
                f"row {row_number} has {len(row)} columns; expected 2"
            )
        records.append({"name": row[0], "note": row[1]})
    return records


def format_records(records: Iterable[Mapping[str, Any]]) -> str:
    """Serialize records to canonical CSV using LF record terminators."""
    if isinstance(records, (str, bytes, Mapping)):
        raise ValueError("records must be an iterable of record mappings")

    output = io.StringIO(newline="")
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow(_HEADER)

    try:
        iterator = iter(records)
    except TypeError as exc:
        raise ValueError("records must be iterable") from exc

    for record_number, record in enumerate(iterator, start=1):
        if not isinstance(record, Mapping):
            raise ValueError(f"record {record_number} must be a mapping")
        try:
            keys = set(record.keys())
        except (TypeError, AttributeError) as exc:
            raise ValueError(f"record {record_number} has invalid keys") from exc
        if keys != {"name", "note"}:
            raise ValueError(
                f"record {record_number} must contain exactly name and note"
            )
        name = record["name"]
        note = record["note"]
        if not isinstance(name, str) or not isinstance(note, str):
            raise ValueError(
                f"record {record_number} values must both be strings"
            )
        writer.writerow([name, note])

    return output.getvalue()


def to_json(text: str) -> str:
    """Convert valid input CSV to JSON without ASCII-escaping Unicode."""
    return json.dumps(parse_records(text), ensure_ascii=False)


def main() -> int:
    try:
        result = to_json(sys.stdin.read())
    except ValueError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 2
    sys.stdout.write(result)
    sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Independent behavioral checks for csv_tool.py.

Run from the repository root with:
    python path/to/this_file.py
Set CSV_TOOL_PATH to test a file in another location.
"""

import importlib.util
import json
import os
from pathlib import Path
import subprocess
import sys
import unittest


def target_path():
    configured = os.environ.get("CSV_TOOL_PATH")
    candidates = []
    if configured:
        candidates.append(Path(configured))
    candidates.append(Path.cwd() / "csv_tool.py")
    here = Path(__file__).resolve()
    candidates.extend(parent / "csv_tool.py" for parent in here.parents)
    for candidate in candidates:
        if candidate.is_file():
            return candidate.resolve()
    raise FileNotFoundError("csv_tool.py not found; run from its directory or set CSV_TOOL_PATH")


TARGET = target_path()
SPEC = importlib.util.spec_from_file_location("csv_tool_under_test", TARGET)
MODULE = importlib.util.module_from_spec(SPEC)
assert SPEC.loader is not None
SPEC.loader.exec_module(MODULE)


class CsvToolBehavior(unittest.TestCase):
    def assert_parse_error(self, text):
        with self.assertRaises(ValueError):
            MODULE.parse_records(text)

    def assert_format_error(self, records):
        with self.assertRaises(ValueError):
            MODULE.format_records(records)

    def run_cli(self, text):
        return subprocess.run(
            [sys.executable, str(TARGET)],
            input=text,
            text=True,
            capture_output=True,
            cwd=str(TARGET.parent),
            check=False,
        )

    # parse_records: valid CSV forms
    def test_01_parse_plain_records(self):
        self.assertEqual(
            MODULE.parse_records("name,note\nAda,first\nGrace,second\n"),
            [{"name": "Ada", "note": "first"}, {"name": "Grace", "note": "second"}],
        )

    def test_02_parse_quoted_comma(self):
        self.assertEqual(
            MODULE.parse_records('name,note\nAda,"one,two"\n'),
            [{"name": "Ada", "note": "one,two"}],
        )

    def test_03_parse_doubled_quote(self):
        self.assertEqual(
            MODULE.parse_records('name,note\nAda,"said ""hello"""\n'),
            [{"name": "Ada", "note": 'said "hello"'}],
        )

    def test_04_parse_embedded_newline(self):
        self.assertEqual(
            MODULE.parse_records('name,note\nAda,"line 1\nline 2"\n'),
            [{"name": "Ada", "note": "line 1\nline 2"}],
        )

    def test_05_parse_crlf_input(self):
        self.assertEqual(
            MODULE.parse_records("name,note\r\nAda,hello\r\nBob,bye\r\n"),
            [{"name": "Ada", "note": "hello"}, {"name": "Bob", "note": "bye"}],
        )

    def test_06_parse_unicode(self):
        self.assertEqual(
            MODULE.parse_records("name,note\nZoë,東京 😀\n"),
            [{"name": "Zoë", "note": "東京 😀"}],
        )

    def test_07_parse_empty_fields(self):
        self.assertEqual(
            MODULE.parse_records("name,note\n,\nAda,\n,empty name\n"),
            [
                {"name": "", "note": ""},
                {"name": "Ada", "note": ""},
                {"name": "", "note": "empty name"},
            ],
        )

    # parse_records: header and syntax rejection
    def test_08_reject_empty_input(self):
        self.assert_parse_error("")

    def test_09_reject_wrong_header_names(self):
        self.assert_parse_error("title,note\nAda,x\n")

    def test_10_reject_wrong_header_case(self):
        self.assert_parse_error("Name,note\nAda,x\n")

    def test_11_reject_extra_header_column(self):
        self.assert_parse_error("name,note,other\nAda,x,y\n")

    def test_12_reject_malformed_unclosed_quote(self):
        self.assert_parse_error('name,note\nAda,"never closed\n')

    def test_13_reject_characters_after_closing_quote(self):
        self.assert_parse_error('name,note\n"Ada"oops,x\n')

    def test_14_reject_record_with_extra_column(self):
        self.assert_parse_error("name,note\nAda,x,unexpected\n")

    def test_15_reject_record_with_missing_column(self):
        self.assert_parse_error("name,note\nAda\n")

    # format_records
    def test_16_format_plain_records_with_lf(self):
        self.assertEqual(
            MODULE.format_records([{"name": "Ada", "note": "first"}]),
            "name,note\nAda,first\n",
        )

    def test_17_format_empty_collection(self):
        self.assertEqual(MODULE.format_records([]), "name,note\n")

    def test_18_format_quotes_special_fields_and_round_trips(self):
        records = [
            {"name": "a,b", "note": 'say "hi"'},
            {"name": "x\ny", "note": "z"},
        ]
        rendered = MODULE.format_records(records)
        self.assertEqual(
            rendered,
            'name,note\n"a,b","say ""hi"""\n"x\ny",z\n',
        )
        self.assertEqual(MODULE.parse_records(rendered), records)

    def test_19_format_preserves_unicode_and_empty_strings(self):
        records = [{"name": "", "note": "雪 ❄"}]
        self.assertEqual(MODULE.parse_records(MODULE.format_records(records)), records)

    def test_20_format_rejects_missing_key(self):
        self.assert_format_error([{"name": "Ada"}])

    def test_21_format_rejects_extra_key(self):
        self.assert_format_error([{"name": "Ada", "note": "x", "extra": "y"}])

    def test_22_format_rejects_non_string_name(self):
        self.assert_format_error([{"name": 7, "note": "x"}])

    def test_23_format_rejects_non_string_note(self):
        self.assert_format_error([{"name": "Ada", "note": None}])

    # JSON conversion and CLI contract
    def test_24_to_json_preserves_exact_values(self):
        text = 'name,note\r\n"Zoë","comma, quote "" and\nnewline 東京"\r\n'
        decoded = json.loads(MODULE.to_json(text))
        self.assertEqual(
            decoded,
            [{"name": "Zoë", "note": 'comma, quote " and\nnewline 東京'}],
        )
        self.assertIsInstance(MODULE.to_json(text), str)

    def test_25_cli_success_is_json_only(self):
        source = 'name,note\n"A, B","hello ""world""\nagain 😀"\n'
        result = self.run_cli(source)
        self.assertEqual(result.returncode, 0)
        self.assertEqual(result.stderr, "")
        self.assertEqual(
            json.loads(result.stdout),
            [{"name": "A, B", "note": 'hello "world"\nagain 😀'}],
        )
        self.assertEqual(result.stdout.strip(), result.stdout.strip().splitlines()[0] if "\\n" in result.stdout else result.stdout.strip())

    def test_26_cli_invalid_input_has_clean_error(self):
        result = self.run_cli('name,note\nAda,"unterminated\n')
        self.assertEqual(result.returncode, 2)
        self.assertEqual(result.stdout, "")
        self.assertTrue(result.stderr.strip(), "invalid input must produce a useful stderr message")
        self.assertNotIn("Traceback", result.stderr)


if __name__ == "__main__":
    unittest.main(verbosity=2)
